 for(let i=-5;i<=5;i++){const bar=new THREE.Mesh(new THREE.BoxGeometry(.035,3.3,.04),new THREE.MeshBasicMaterial({color:i%2?0x8e36ff:0xff36b8}));bar.position.set(i*.72,1.6,-4.8);scene.add(bar)}
 const dust=new THREE.Group();scene.add(dust);for(let i=0;i<55;i++){const p=blob(dust,i%2?cyan:pink,[0,0,0],[.018,.018,.018],8);p.position.set((Math.random()-.5)*8,Math.random()*4-0.1,-2-Math.random()*5)}
 let running=false,startedAt=0,lastBeat=-1,score=0,streak=0,view='orbit',viewTarget=null,orbitAngle=0,dragging=false,prevX=0,audio=null,sound=false;const cue=document.querySelector('#cue'),meter=document.querySelector('#meter');
 function begin(){running=true;startedAt=performance.now()/1000;lastBeat=-1;document.querySelector('#overlay').classList.add('hide');cue.textContent='Prepare-se...'}
-function tap(){if(!running){begin();return}const t=performance.now()/1000-startedAt;const phase=(t%1.15);const err=Math.min(phase,1.15-phase);if(err<.20){const quality=err<.085?'PERFEITO!':'NO TEMPO!';score+=err<.085?100:55;streak++;document.querySelector('#hit').textContent=quality;document.querySelector('#hit').classList.add('show');cue.textContent='✦ Boa! Continue no ritmo';setTimeout(()=>document.querySelector('#hit').classList.remove('show'),360);if(sound&&audio)tone(err<.085?880:660)}else{streak=0;cue.textContent='Siga o pulso neon';if(sound&&audio)tone(180)}document.querySelector('#score').textContent=String(score).padStart(4,'0');document.querySelector('#streak').textContent='SEQUÊNCIA ×'+streak}
+function tap(){if(!running){begin();return}const t=performance.now()/1000-startedAt;const phase=(t%1.15);const err=Math.abs(phase-.575);if(err<.20){const quality=err<.085?'PERFEITO!':'NO TEMPO!';score+=err<.085?100:55;streak++;document.querySelector('#hit').textContent=quality;document.querySelector('#hit').classList.add('show');cue.textContent='✦ Boa! Continue no ritmo';setTimeout(()=>document.querySelector('#hit').classList.remove('show'),360);if(sound&&audio)tone(err<.085?880:660)}else{streak=0;cue.textContent='Siga o pulso neon';if(sound&&audio)tone(180)}document.querySelector('#score').textContent=String(score).padStart(4,'0');document.querySelector('#streak').textContent='SEQUÊNCIA ×'+streak}
 function tone(freq){const o=audio.createOscillator(),gain=audio.createGain();o.frequency.value=freq;o.type='sine';gain.gain.setValueAtTime(.08,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.connect(gain);gain.connect(audio.destination);o.start();o.stop(audio.currentTime+.13)}
 document.querySelector('#start').onclick=begin;document.querySelector('#dance').onclick=tap;renderer.domElement.addEventListener('pointerdown',e=>{dragging=true;prevX=e.clientX;renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(dragging){orbitAngle+=(e.clientX-prevX)*.009;view='manual';prevX=e.clientX}});renderer.domElement.addEventListener('pointerup',()=>dragging=false);window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();tap()}});
 document.querySelectorAll('.cam').forEach(b=>b.onclick=()=>{document.querySelectorAll('.cam').forEach(x=>x.classList.remove('active'));b.classList.add('active');view=b.dataset.view;viewTarget={front:0,side:Math.PI/2,back:Math.PI}[view]??null});document.querySelector('#soundBtn').onclick=()=>{sound=!sound;if(sound)audio??=new AudioContext();document.querySelector('#soundBtn').textContent='♪ SOM: '+(sound?'ON':'OFF')};
 window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});

