 let clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const dt=clock.getDelta(),t=clock.elapsedTime;if(view==='orbit'&&!dragging)orbitAngle+=dt*.10;if(viewTarget!==null){let delta=viewTarget-orbitAngle;while(delta>Math.PI)delta-=Math.PI*2;while(delta<-Math.PI)delta+=Math.PI*2;orbitAngle+=delta*Math.min(dt*2.7,1);if(Math.abs(delta)<.012)viewTarget=null}
 const radius=12.5;camera.position.set(Math.sin(orbitAngle)*radius,3.65+Math.sin(t*.35)*.12,Math.cos(orbitAngle)*radius);camera.lookAt(0,2.05,0);
 dancers.forEach((d,i)=>{const ph=t*2.7+d.userData.phase;d.position.y=Math.sin(ph)*.045;d.rotation.z=Math.sin(ph*.5+i)*.04;d.rotation.y=(i===0?-.09:.09)+Math.sin(ph*.7)*.09;d.scale.x=(i===0?1.04:.91)*(1+Math.sin(ph)*.012)});
 rings.forEach((r,i)=>{r.material.color.setHSL((t*.12+i*.31)%1,.9,.65);r.scale.setScalar(1+Math.sin(t*2+i)*.012)});dust.rotation.y=t*.025;
-if(running){const elapsed=performance.now()/1000-startedAt;const phase=elapsed%1.15;meter.style.width=(Math.max(0,1-Math.abs(phase-.575)/.575)*100)+'%';const beat=Math.floor(elapsed/1.15);if(beat!==lastBeat){lastBeat=beat;cue.textContent='TOQUE! ✦';if(sound&&audio)tone(440)} }
+if(running){const elapsed=performance.now()/1000-startedAt;const phase=elapsed%1.15;meter.style.width=(Math.max(0,1-Math.abs(phase-.575)/.575)*100)+'%';const beat=Math.floor(elapsed/1.15);if(phase>.56&&phase<.60&&beat!==lastBeat){lastBeat=beat;cue.textContent='TOQUE! ✦';if(sound&&audio)tone(440)} }
 renderer.render(scene,camera)}animate();
